import { Component, OnInit } from '@angular/core';
import { GlobalService } from '../service/global.service';
@Component({
  selector: 'app-landing',
  templateUrl: './landing.component.html',
  styleUrls: ['./landing.component.css'],
})
export class LandingComponent implements OnInit {
  constructor(private globalService: GlobalService) {}
  ngOnInit(): void {
    console.log('@@@@@@@@' + this.globalService.APPLICATION_STATE);
  }
}
<!DOCTYPE html>
<html lang="en">
  <body>
    <section class="hero">
      <div>
        <meta charset="UTF-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1.0" />
        <title>Landing Page</title>
        <link rel="stylesheet" />
      </div>
      <div class="hero-content">
        <h1 class="hero-title">Welcome to the Aurora Project</h1>
        <a href="#" class="cta-button" routerLink="/login">Get Started</a>
      </div>
    </section>
  </body>
  <footer>
    <p>&copy; 2023 Project Aurora. All rights reserved.</p>
  </footer>
</html>
